  "complete_original_Quran_parents": [
    {
      "id": "2:3",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/2/3",
      "parent": {
        "id": "10",
        "sura": "2",
        "aya": "3",
        "arabic_text": "ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ",
        "translation": "वे लोग जो ग़ैब (परोक्ष)[1] पर ईमान लाते हैं, और नमाज़ की स्थापना करते हैं और जो कुछ हमने उन्हें दिया है, उसमें से ख़र्च करते हैं।",
        "footnotes": "[1] इस्लाम की परिभाषा में, अल्लाह, उसके फ़रिश्तों, उसकी पुस्तकों, उसके रसूलों तथा अंतिम दिन (प्रलय) और अच्छे-बुरे भाग्य पर ईमान (विश्वास) को 'ईमान बिल ग़ैब' कहा गया है। (इब्ने कसीर)"
      }
    },
    {
      "id": "2:55",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/2/55",
      "parent": {
        "id": "62",
        "sura": "2",
        "aya": "55",
        "arabic_text": "وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ",
        "translation": "तथा (वह समय याद करो) जब तुमने कहा : ऐ मूसा! हम कदापि तुम्हारा विश्वास नहीं करेंगे, यहाँ तक कि हम अल्लाह को खुल्लम-खुल्ला देख लें! तो तुम्हें बिजली की कड़क ने पकड़ लिया और तुम देख रहे थे।",
        "footnotes": ""
      }
    },
    {
      "id": "2:77",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/2/77",
      "parent": {
        "id": "84",
        "sura": "2",
        "aya": "77",
        "arabic_text": "أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ",
        "translation": "और क्या वे नहीं जानते कि निःसंदेह अल्लाह जानता है, जो कुछ वे छिपाते हैं और जो कुछ ज़ाहिर करते हैं?",
        "footnotes": ""
      }
    },
    {
      "id": "2:186",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/2/186",
      "parent": {
        "id": "193",
        "sura": "2",
        "aya": "186",
        "arabic_text": "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ",
        "translation": "और (ऐ नबी!) जब मेरे बंदे आपसे मेरे बारे में पूछें, तो निश्चय मैं (उनसे) क़रीब हूँ। मैं पुकारने वाले की दुआ क़बूल करता हूँ जब वह मुझे पुकारता है। तो उन्हें चाहिए कि वे मेरी बात मानें तथा मुझपर ईमान लाएँ, ताकि वे मार्गदर्शन पाएँ।",
        "footnotes": ""
      }
    },
    {
      "id": "2:255",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/2/255",
      "parent": {
        "id": "262",
        "sura": "2",
        "aya": "255",
        "arabic_text": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ",
        "translation": "अल्लाह (वह है कि) उसके सिवा कोई पूज्य नहीं। (वह) जीवित है, हर चीज़ को सँभालने (क़ायम रखने)[170] वाला है। न उसे कुछ ऊँघ पकड़ती है और न नींद। उसी का है जो कुछ आकाशों में और जो कुछ धरती में है। कौन है, जो उसके पास उसकी अनुमति के बिना अनुशंसा (सिफ़ारिश) करे? वह जानता है जो कुछ उनके सामने और जो कुछ उनके पीछे है। और वे उसके ज्ञान में से किसी चीज़ को (अपने ज्ञान से) नहीं घेर सकते, परंतु जितना वह चाहे। उसकी कुर्सी आकाशों और धरती को व्याप्त है और उन दोनों की रक्षा उसे नहीं थकाती। और वही सबसे ऊँचा, सबसे महान है।[171]",
        "footnotes": "[170] अर्थात जो स्वयं स्थित तथा सब उसकी सहायता से स्थित हैं।\n[171] यह क़ुरआन की सबसे महान आयत है। और इसका नाम \"आयतुल कुर्सी\" है। ह़दीस में इसकी बड़ी प्रधानता बताई गई है। (तफ़सीर इब्ने कसीर)"
      }
    },
    {
      "id": "3:123",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/3/123",
      "parent": {
        "id": "416",
        "sura": "3",
        "aya": "123",
        "arabic_text": "وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ",
        "translation": "और अल्लाह बद्र (के युद्ध) में तुम्हारी सहायता कर चुका है, जबकि तुम कमज़ोर थे। अतः अल्लाह से डरो, ताकि तुम उसके प्रति आभारी हो सको।",
        "footnotes": ""
      }
    },
    {
      "id": "3:136",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/3/136",
      "parent": {
        "id": "429",
        "sura": "3",
        "aya": "136",
        "arabic_text": "أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ",
        "translation": "वही लोग हैं जिनका बदला उनके पालनहार की ओर से क्षमा तथा ऐसे बाग़ हैं जिनके नीचे से नहरें बहती होंगी। उनमें वे सदैव रहेंगे। औ क्या ही अच्छा बदला है नेक काम करने वालों का।",
        "footnotes": ""
      }
    },
    {
      "id": "3:140",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/3/140",
      "parent": {
        "id": "433",
        "sura": "3",
        "aya": "140",
        "arabic_text": "إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ",
        "translation": "यदि तुम्हें आघात पहुँचा है, तो उन लोगों[76] को भी इसी के समान आघात पहुँच चुका है। तथा इन दिनों को हम लोगों के बीच फेरते रहते[77] हैं। और ताकि अल्लाह उन लोगों को जान ले[78] जो ईमान वाले हैं, और तुममें से कुछ लोगों को शहादत नसीब करे। और अल्लाह अत्याचार करने वालों को पसंद नहीं करता।",
        "footnotes": "[76] इसमें क़ुरैश की बद्र में पराजय और उनके 70 व्यक्तियों के मारे जाने की ओर संकेत है। \n[77] अर्थात कभी किसी की जीत होती है, कभी किसी की। \n[78] अर्थात अच्छे बुरे में अंतर कर दे।"
      }
    },
    {
      "id": "3:173",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/3/173",
      "parent": {
        "id": "466",
        "sura": "3",
        "aya": "173",
        "arabic_text": "ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ",
        "translation": "ये वही लोग हैं जिनसे लोगों ने कहा कि दुश्मनों ने तुम्हारे विरुद्ध सेना इकट्ठा कर ली है।[97] अतः उनसे डरो। तो इस (सूचना) ने उनके ईमान को और बढ़ा दिया और उन्होंने कहा : हमारे लिए अल्लाह काफ़ी है और वह बहुत अच्छा कार्यसाधक (काम बनाने वाला) है।",
        "footnotes": "[97] अर्थात शत्रु ने मक्का जाते हुए राह में सोचा कि मुसलमानों के परास्त हो जाने पर यह अच्छा अवसर था कि मदीने पर आक्रमण करके उनका उन्मू222लन कर दिया जाए, तथा वापस आने का निश्चय किया। (तफ़्सीर क़ुर्तुबी)"
      }
    },
    {
      "id": "6:14",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/6/14",
      "parent": {
        "id": "803",
        "sura": "6",
        "aya": "14",
        "arabic_text": "قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ",
        "translation": "(ऐ नबी!) कह दो : क्या मैं अल्लाह के सिवा कोई सहायक बनाऊँ, जो आकाशों तथा धरती का बनाने वाला है, हालाँकि वह खिलाता है और उसे नहीं खिलाया जाता। आप कहिए : निःसंदेह मुझे आदेश दिया गया है कि सबसे पहला व्यक्ति बनूँ जो आज्ञाकारी हुआ, तथा तुम कदापि साझी बनाने वालों में से न हो।",
        "footnotes": ""
      }
    },
    {
      "id": "6:82",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/6/82",
      "parent": {
        "id": "871",
        "sura": "6",
        "aya": "82",
        "arabic_text": "ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ",
        "translation": "जो लोग ईमान लाए और उन्होंने अपने ईमान को अत्याचार (शिर्क) के साथ नहीं मिलाया[57], यही लोग हैं जिनके लिए शांति है तथा वही मार्गदर्शन पाने वाले हैं।",
        "footnotes": "[57] ह़दीस में है कि जब यह आयत उतरी तो नबी सल्लल्लाहु अलैहि व सल्लम के साथियों ने कहा : हममें कौन है जिसने अत्याचार न किया हो? उस समय वह आयत उतरी, जिसका अर्थ यह है कि निश्चय शिर्क (मिश्रणवाद) ही सबसे बड़ा अत्याचार है। (सह़ीह़ बुख़ारी : 4629)"
      }
    },
    {
      "id": "7:138",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/7/138",
      "parent": {
        "id": "1092",
        "sura": "7",
        "aya": "138",
        "arabic_text": "وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ",
        "translation": "और हमने बनी इसराईल को सागर के पार उतार दिया। तो वे एक ऐसी जाति पर आए, जो अपनी कुछ मूर्तियों पर जमी बैठी थी। उन्होंने कहा : ऐ मूसा! हमारे लिए कोई पूज्य बना दीजिए, जैसे इनके कुछ पूज्य हैं। (मूसा ने) कहा : निःसंदेह तुम ऐसे लोग हो जो नादानी करते हो।",
        "footnotes": ""
      }
    },
    {
      "id": "8:10",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/8/10",
      "parent": {
        "id": "1170",
        "sura": "8",
        "aya": "10",
        "arabic_text": "وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ",
        "translation": "और अल्लाह ने यह इसलिए किया कि (तुम्हारे लिए) शुभ सूचना हो और ताकि इसके साथ तुम्हारे दिल संतुष्ट हो जाएँ। अन्यथा सहायता तो अल्लाह ही की ओर से होती है। निःसंदेह अल्लाह सब पर प्रभुत्वशाली, पूर्ण हिकमत वाला है।",
        "footnotes": ""
      }
    },
    {
      "id": "9:40",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/9/40",
      "parent": {
        "id": "1275",
        "sura": "9",
        "aya": "40",
        "arabic_text": "إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ",
        "translation": "यदि तुम उनकी सहायता न करो, तो निःसंदेह अल्लाह ने उनकी सहायता की, जब उन्हें उन लोगों ने निकाल दिया[20] जिन्होंने कुफ़्र किया, जब वह दो में दूसरा थे, जब वे दोनों गुफा में थे, जब वह अपने साथी से कह रहे थे : शोकाकुल न हो। निःसंदेह अल्लाह हमारे साथ है।[21] तो अल्लाह ने उनपर अपनी ओर से शांति उतार दी और उन्हें ऐसी सेनाओँ के साथ शक्ति प्रदान की, जिन्हें तुमने नहीं देखे और उन लोगों की बात नीची कर दी जिन्होंने कुफ़्र किया, और अल्लाह की बात ही सबसे ऊँची है और अल्लाह सबपर प्रभुत्वशाली, पूर्ण हिकमत वाला है।",
        "footnotes": "[20] यह उस अवसर की चर्चा है जब मक्का के मिश्रणवादियों ने नबी सल्लल्लाहु अलैहि व सल्लम का वध कर देने का निर्णय किया। उसी रात आप मक्का से निकलकर 'सौर' पर्वत की चोटी के पास स्थित गुफा में तीन दिन तक छिपे रहे। फिर मदीना पहुँचे। उस समय गुफा में केवल आदरणीय अबू बक्र सिद्दीक़ रज़ियल्लाहु अन्हु आपके साथ थे। \n[21] ह़दीस में है कि अबू बक्र (रज़ियल्लाहु अन्हु) ने कहा कि मैं गुफा में नबी (सल्लल्लाहु अलैहि व सल्लम) के साथ था। और मैंने मुश्रिकों के पैर देख लिए। और आपसे कहा : यदि इनमें से कोई अपना पैर उठा दे, तो हमें देख लेगा। आपने कहा : उन दो के बारे में तुम्हारा क्या विचार है जिनका तीसरा अल्लाह है। (सह़ीह़ बुख़ारी : 4663)"
      }
    },
    {
      "id": "11:55",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/11/55",
      "parent": {
        "id": "1528",
        "sura": "11",
        "aya": "55",
        "arabic_text": "مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ",
        "translation": "उस (अल्लाह) के सिवा। अतः तुम सब मिलकर मेरे विरुद्ध चाल चलो, फिर मुझे मोहलत न दो।[16]",
        "footnotes": "[16] अर्थात तुम और तुम्हारे सब देवी-देवता मिलकर भी मेरा कुछ बिगाड़ नहीं सकते। क्योंकि मेरा भरोसा जिस अल्लाह पर है, पूरा संसार उसके नियंत्रण में है, उसके आगे किसी की शक्ति नहीं कि किसी का कुछ बिगाड़ सके।"
      }
    },
    {
      "id": "11:56",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/11/56",
      "parent": {
        "id": "1529",
        "sura": "11",
        "aya": "56",
        "arabic_text": "إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ",
        "translation": "निःसंदेह मैंने अपने पालनहार और तुम्हारे पालनहार, अल्लाह पर भरोसा किया है। कोई चलने वाला जीव नहीं, परंतु वह उसके माथे के बालों को पकड़े हुए है। निश्चय ही मेरा पालनहार सीधे रास्ते[17] पर है।",
        "footnotes": "[17] अर्थात उसका रास्ता अत्याचार का रास्ता नहीं हो सकता कि तुम दुराचारी और कुपथ में रहकर सफल रहो और मैं सदाचारी रहकर हानि में पड़ूँ।"
      }
    },
    {
      "id": "12:33",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/12/33",
      "parent": {
        "id": "1629",
        "sura": "12",
        "aya": "33",
        "arabic_text": "قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ",
        "translation": "यूसुफ़ ने प्रार्थना की : ऐ मेरे पालनहार! मुझे क़ैद उससे अधिक प्रिय है, जिसकी ओर ये औरतें मुझे बुला रही हैं। और यदि तूने मुझसे इनके छल को दूर नहीं किया, तो मैं इनकी ओर झुक जाऊँगा और अज्ञानियों में से हो जाऊँगा।",
        "footnotes": ""
      }
    },
    {
      "id": "12:34",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/12/34",
      "parent": {
        "id": "1630",
        "sura": "12",
        "aya": "34",
        "arabic_text": "فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ",
        "translation": "तो उसके पालनहार ने उसकी प्रार्थना स्वीकार कर ली और उससे उनके छल को दूर कर दिया। निःसंदेह वह बड़ा सुनने वाला, बड़ा जानने वाला है।",
        "footnotes": ""
      }
    },
    {
      "id": "18:7",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/18/7",
      "parent": {
        "id": "2147",
        "sura": "18",
        "aya": "7",
        "arabic_text": "إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا",
        "translation": "निःसंदेह जो कुछ धरती के ऊपर है, हमने उसे उसकी शोभा बनाया है। ताकि हम उनका परीक्षण करें कि उनमें कौन कर्म की दृष्टि से सबसे अच्छा है?",
        "footnotes": ""
      }
    },
    {
      "id": "19:65",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/19/65",
      "parent": {
        "id": "2315",
        "sura": "19",
        "aya": "65",
        "arabic_text": "رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا",
        "translation": "जो आकाशों और धरती का और उन दोनों के बीच की चीज़ों का पालनहार है। अतः उसी की इबादत करें तथा उसकी इबादत पर पर दृढ़ रहें। क्या आप उसका समकक्ष किसी को जानते हैं?",
        "footnotes": ""
      }
    },
    {
      "id": "19:90",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/19/90",
      "parent": {
        "id": "2340",
        "sura": "19",
        "aya": "90",
        "arabic_text": "تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا",
        "translation": "समीप है कि इस कथन के कारण आकाश फट पड़ें तथा धरती चिर जाए और और पहाड़ ध्वस्त होकर गिर पड़ें।",
        "footnotes": ""
      }
    },
    {
      "id": "19:91",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/19/91",
      "parent": {
        "id": "2341",
        "sura": "19",
        "aya": "91",
        "arabic_text": "أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا",
        "translation": "इस बात पर कि उन्होंने रहमान की संतान होने का दावा किया।",
        "footnotes": ""
      }
    },
    {
      "id": "21:69",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/21/69",
      "parent": {
        "id": "2552",
        "sura": "21",
        "aya": "69",
        "arabic_text": "قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ",
        "translation": "हमने कहा : ऐ आग! तू इबराहीम पर ठंडक और सुरक्षा सुरक्षा बन जा।",
        "footnotes": ""
      }
    },
    {
      "id": "21:87",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/21/87",
      "parent": {
        "id": "2570",
        "sura": "21",
        "aya": "87",
        "arabic_text": "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ",
        "translation": "तथा मछली वाले[34] (की कहानी याद करो), जब वह ग़ुस्से से भरा हुआ चला गया[35] और उसने सोचा कि हम उसे तंगी में नहीं डालेंगे। अंततः उसने अंधेरों में पुकारा कि (ऐ अल्लाह!) तेरे सिवा कोई पूज्य नहीं, तू पवित्र है। निश्चय मैं ही अत्याचारियों में हो गया।[36]",
        "footnotes": "[34] इससे अभिप्रेत यूनुस अलैहिस्सलाम हैं। उनको ''ज़ुन्नून'' और \"साह़िबुल ह़ूत\" कहा गया है। अर्थात मछली वाला। क्योंकि उनको अल्लाह के आदेश से एक मछली ने निगल लिया था। इसका कुछ वर्णन सूरत यूनुस में आ चुका है। और कुछ सूरतुस-साफ़्फ़ात में आ रहा है।\n[35] अर्थात अपनी जाति से क्रोधित होकर अल्लाह के अनुमति के बिना अपनी बस्ती से चले गए। इसी पर उन्हें पकड़ लिया गया।\n[36] सह़ीह़ ह़दीस में आता है कि जो भी मुसलमान इस शब्द के साथ किसी विषय में दुआ करेगा तो अल्लाह उसकी दुआ को स्वीकार करेगा। (तिर्मिज़ी : 3505)"
      }
    },
    {
      "id": "21:88",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/21/88",
      "parent": {
        "id": "2571",
        "sura": "21",
        "aya": "88",
        "arabic_text": "فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ",
        "translation": "तो हमने उनकी दुआ क़बूल की तथा उन्हें शोक से मुक्त कर दिया। और इसी तरह हम ईमान वालों को बचा लिया करते हैं।",
        "footnotes": ""
      }
    },
    {
      "id": "22:11",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/22/11",
      "parent": {
        "id": "2606",
        "sura": "22",
        "aya": "11",
        "arabic_text": "وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ",
        "translation": "तथा लोगों में वह (भी) है, जो अल्लाह की इबादत एक किनारे पर रहकर[5] करता है। फिर यदि उसे कोई भलाई पहुँच जाए, तो वह उससे संतुष्ट हो जाता है, और यदि उसे कोई परीक्षा आ पहुँचे, तो मुँह के बल फिर जाता है। वह दुनिया एवं आख़िरत में घाटे में पड़ गया। यही तो खुला घाटा है।",
        "footnotes": "[5] अर्थात संदिग्ध होकर।"
      }
    },
    {
      "id": "25:58",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/25/58",
      "parent": {
        "id": "2913",
        "sura": "25",
        "aya": "58",
        "arabic_text": "وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا",
        "translation": "तथा उस सदा जीवंत पर भरोसा कीजिए, जो कभी नहीं मरेगा। और उसकी प्रशंसा के साथ पवित्रता का गान कीजिए। और वह अपने बंदों के गुनाहों की पूरी ख़बर रखने वाला काफ़ी है।",
        "footnotes": ""
      }
    },
    {
      "id": "28:7",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/28/7",
      "parent": {
        "id": "3259",
        "sura": "28",
        "aya": "7",
        "arabic_text": "وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ",
        "translation": "और हमने मूसा की माँ की ओर वह़्य की[3] कि उसे दूध पिला, फिर जब तुझे उसके बारे में भय हो, तो उसे दरिया में डाल दे और न डर और न शोक कर। निःसंदेह हम उसे तेरी ओर वापस लाने वाले हैं और उसे रसूलों में से बनाने वाले हैं।",
        "footnotes": "[3] जब मूसा का जन्म हुआ, तो अल्लाह ने उनके माता के मन में ये बातें डाल दीं।"
      }
    },
    {
      "id": "28:16",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/28/16",
      "parent": {
        "id": "3268",
        "sura": "28",
        "aya": "16",
        "arabic_text": "قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ",
        "translation": "उसने कहा : ऐ मेरे पालनहार! निश्चय ही मैंने अपने ऊपर अत्याचार किया है, अतः मुझे क्षमा कर दे। तो उसने उसे क्षमा कर दिया, निःसंदेह वही बड़ा क्षमाशील, अत्यंत दयावान है।",
        "footnotes": ""
      }
    },
    {
      "id": "39:29",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/39/29",
      "parent": {
        "id": "4087",
        "sura": "39",
        "aya": "29",
        "arabic_text": "ضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلٗا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلٗا سَلَمٗا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ",
        "translation": "अल्लाह ने एक व्यक्ति का उदाहरण दिया है, जिसमें कई परस्पर विरोधी साझी हैं तथा एक और व्यक्ति का, जो पूरा एक ही व्यक्ति का (दास) है। क्या दोनों की स्थिति समान हैं?[5] सब प्रशंसा अल्लाह के लिए है। बल्कि उनमें से अधिकतर लोग नहीं जानते।",
        "footnotes": "[5] इस आयत में मिश्रणवादी और एकेश्वरवादी की दशा का वर्णन किया गया है कि मिश्रणवादी अनेक पूज्यों को प्रसन्न करने में व्याकुल रहता है। तथा एकेश्वरवादी शांत होकर केवल एक अल्लाह की इबादत करता है और एक ही को प्रसन्न करता है।"
      }
    },
    {
      "id": "42:11",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/42/11",
      "parent": {
        "id": "4283",
        "sura": "42",
        "aya": "11",
        "arabic_text": "فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ",
        "translation": "(वह) आकाशों तथा धरती का रचयिता है। उसने तुम्हारे लिए तुम्हारी अपनी ही जाति से जोड़े बनाए तथा पशुओं से भी जोड़े। वह तुम्हें इसमें फैलाता है। उसके जैसी[9] कोई चीज़ नहीं और वह सब कुछ सुनने वाला, सब कुछ देखने वाला है।",
        "footnotes": "[9] अर्थात उसके अस्तित्व तथा गुण और कर्म में कोई उसके समान नहीं है। भावार्थ यह है कि किसी व्यक्ति या वस्तु में उसका गुण या कर्म मानना या उसे उसका अंश मानना, असत्य तथा अधर्म है।"
      }
    },
    {
      "id": "42:52",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/42/52",
      "parent": {
        "id": "4324",
        "sura": "42",
        "aya": "52",
        "arabic_text": "وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ",
        "translation": "और इसी प्रकार हमने आपकी ओर अपने आदेश से एक रूह़ (क़ुरआन) की वह़्य की। आप नहीं जानते थे कि पुस्तक क्या है और न यह कि ईमान[35] क्या है। परंतु हमने उसे एक ऐसा प्रकाश बनाया दिया है, जिसके द्वारा हम अपने बंदों में से जिसे चाहते हैं, मार्ग दिखाते हैं। और निःसंदेह आप सीधी राह[36] की ओर मार्गदर्शन करते हैं।",
        "footnotes": "[35] मक्का वासियों को यह आश्चर्य था कि मनुष्य अल्लाह का नबी कैसे हो सकता है? इसपर क़ुरआन बता रहा है कि आप नबी होने से पहले न तो किसी आकाशीय पुस्तक से अवगत थे और न कभी ईमान की बात ही आपके विचार में आई। और यह दोनों बातें ऐसी थीं जिनका मक्कावासी भी इनकार नहीं कर सकते थे। और यही आपका अपढ़ होना आपके सत्य नबी होने का प्रमाण है। जिसे क़ुरआन की अनेक आयतों में वर्णन किया गया है।\n[36] सीधी राह से अभिप्राय सत्धर्म इस्लाम है।"
      }
    },
    {
      "id": "55:29",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/55/29",
      "parent": {
        "id": "4930",
        "sura": "55",
        "aya": "29",
        "arabic_text": "يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ",
        "translation": "उसी से माँगता है, जो कोई आकाशों तथा धरती में है। वह प्रतिदिन एक (नए) कार्य में है।[3]",
        "footnotes": "[3] अर्थात वह अपनी उत्पत्ति की आवश्यकताएँ पूरी करता, प्रार्थनाएँ सुनता, सहायता करता, रोगी को निरोग करता, अपनी दया प्रदान करता, तथा अपमान-सम्मान और विजय-प्राजय देता और अनगिनत कार्य करता है।"
      }
    },
    {
      "id": "57:3",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/57/3",
      "parent": {
        "id": "5078",
        "sura": "57",
        "aya": "3",
        "arabic_text": "هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ",
        "translation": "वही सबसे पहले है और सबसे आख़िर है और ज़ाहिर (दृश्यमान) है और पोशीदा (अदृश्य) है और वह हर चीज़ को भली-भाँति जानने वाला है।",
        "footnotes": ""
      }
    },
    {
      "id": "67:14",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/67/14",
      "parent": {
        "id": "5255",
        "sura": "67",
        "aya": "14",
        "arabic_text": "أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ",
        "translation": "क्या वह नहीं जानेगा जिसने पैदा किया?! जबकि वह सूक्ष्मदर्शी[5], पूर्ण ख़बर रखने वाला है।",
        "footnotes": "[5] बारीक बातों को जानने वाला।"
      }
    },
    {
      "id": "68:51",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/68/51",
      "parent": {
        "id": "5322",
        "sura": "68",
        "aya": "51",
        "arabic_text": "وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ",
        "translation": "और वे लोग जिन्होंने इनकार किया, निश्चय क़रीब हैं कि वे अपनी निगाहों से (घूर घूरकर) आपको अवश्य ही फिसला देंगे, जब वे क़ुरआन को सुनते हैं और कहते हैं कि यह अवश्य ही दीवाना है।",
        "footnotes": ""
      }
    },
    {
      "id": "72:2",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/72/2",
      "parent": {
        "id": "5449",
        "sura": "72",
        "aya": "2",
        "arabic_text": "يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا",
        "translation": "जो सीधी राह दिखाता है, तो हम उसपर ईमान ले आए और (अब) हम अपने पालनहार के साथ किसी को कभी साझी नहीं बनाएँगे।",
        "footnotes": ""
      }
    },
    {
      "id": "73:6",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/73/6",
      "parent": {
        "id": "5481",
        "sura": "73",
        "aya": "6",
        "arabic_text": "إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا",
        "translation": "निःसंदेह रात की इबादत हृदय में अधिक प्रभावी होती है और बात के लिए अधिक उपयुक्त होती है।",
        "footnotes": ""
      }
    },
    {
      "id": "112:1",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/112/1",
      "parent": {
        "id": "6222",
        "sura": "112",
        "aya": "1",
        "arabic_text": "قُلۡ هُوَ ٱللَّهُ أَحَدٌ",
        "translation": "(ऐ रसूल!) आप कह दीजिए : वह अल्लाह एक है।[1]",
        "footnotes": "[1] आयत संख्या 1 में 'अह़द' शब्द का प्रयोग हुआ है जिसका अर्थ है, उसके अस्तित्व एवं गुणों में कोई साझी नहीं है। यहाँ 'अह़द' शब्द का प्रयोग यह बताने के लिए किया गया है कि वह अकेला है। वह वृक्ष के समान एक नहीं है जिसकी अनेक शाखाएँ होती हैं। आयत संख्या 2 में 'समद' शब्द का प्रयोग हुआ है, जिसका अर्थ है अब्रण होना। अर्थात जिसमें कोई छिद्र न हो जिससे कुछ निकले, या वह किसी से निकले। और आयत संख्या 3 इसी अर्थ की व्याख्या करती है कि न उसकी कोई संतान है और न वह किसी की संतान है।"
      }
    },
    {
      "id": "112:2",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/112/2",
      "parent": {
        "id": "6223",
        "sura": "112",
        "aya": "2",
        "arabic_text": "ٱللَّهُ ٱلصَّمَدُ",
        "translation": "अल्लाह बेनियाज़ है।",
        "footnotes": ""
      }
    },
    {
      "id": "112:3",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/112/3",
      "parent": {
        "id": "6224",
        "sura": "112",
        "aya": "3",
        "arabic_text": "لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ",
        "translation": "न उसकी कोई संतान है और न वह किसी की संतान है।",
        "footnotes": ""
      }
    },
    {
      "id": "112:4",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/112/4",
      "parent": {
        "id": "6225",
        "sura": "112",
        "aya": "4",
        "arabic_text": "وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ",
        "translation": "और न कोई उसका समकक्ष है।[2]",
        "footnotes": "[2] इस आयत में यह बताया गया है कि उसकी प्रतिमा तथा उसके बराबर और समतुल्य कोई नहीं है। उसके कर्म, गुण और अधिकार में कोई किसी रूप में बराबर नहीं। न उसकी कोई जाति है न परिवार। इन आयतों में क़ुरआन उन विषयों को जो लोगों के तौह़ीद से फिसलने का कारण बने, उसे अनेक रूप में वर्णित करता है। और देवियों और देवताओं के विवाहों और उन के पुत्र और पौत्रों का जो विवरण देव मालाओं में मिलता है, क़ुरआन ने उसका खंडन किया है।"
      }
    },
    {
      "id": "113:1",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/113/1",
      "parent": {
        "id": "6226",
        "sura": "113",
        "aya": "1",
        "arabic_text": "قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ",
        "translation": "(ऐ नबी!) कह दीजिए : मैं सुबह के पालनहार की शरण लेता हूँ।",
        "footnotes": ""
      }
    },
    {
      "id": "114:1",
      "url": "https://quranenc.com/api/v1/translation/aya/hindi_omari/114/1",
      "parent": {
        "id": "6231",
        "sura": "114",
        "aya": "1",
        "arabic_text": "قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ",
        "translation": "(ऐ नबी!) कह दीजिए : मैं शरण लेता हूँ लोगों के पालनहार की।",
        "footnotes": ""
      }
    }
  ],
