            "hindi": "अल्लाह थोड़े-से शब्दों में अपना परिचय देता है, जिनमें दिल के लिए एक ऐसी बुनियादी सच्चाई है जिसके बिना उसका काम नहीं चल सकता: «(ऐ रसूल!) आप कह दीजिए : वह अल्लाह एक है।[1]»",
            "quote_bindings": [
              "Q:1"
            ]
          },
          {
            "id": "p05.s02",
            "arabic": "فمن رحمته أنه لم يهيئ للناس طعام أبدانهم ثم يترك أرواحهم بلا هدى؛ أرسل الرسل وأنزل الكتب، وجعل وحيه حياةً ونورًا، كما قال: ﴿وَكَذَٰلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِنْ أَمْرِنَا﴾ [الشورى: 52].",
            "hindi": "यह उसकी दया है कि उसने लोगों के शरीर के लिए भोजन का प्रबंध करके उनकी आत्माओं को मार्गदर्शन के बिना नहीं छोड़ दिया; उसने रसूल भेजे, किताबें उतारीं और अपनी वह्य को जीवन और प्रकाश बनाया, जैसा कि उसने फ़रमाया: «और इसी प्रकार हमने आपकी ओर अपने आदेश से एक रूह़ (क़ुरआन) की वह़्य की।»",
            "quote_bindings": [
              "Q:2"
            ]
          },
          {
            "id": "p05.s03",
            "arabic": "ومن أعظم ما يحيي به هذا الوحي القلب أن يعرّفه بربه.",
            "hindi": "यह वह्य जिन बड़ी बातों से दिल को जीवन देती है, उनमें से एक यह है कि वह उसे उसके रब से परिचित कराती है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s04",
            "arabic": "ولهذا لا تُقرأ سورة الإخلاص على أنها كلمات يعرفها المسلم منذ طفولته فلا يحتاج إلى الوقوف عندها؛ فقد تبقى ألفاظها محفوظة، بينما يغيب أثرها عن خوفه ورجائه واختياراته.",
            "hindi": "इसलिए सूरा इख़लास को केवल ऐसे शब्द समझकर नहीं पढ़ना चाहिए जिन्हें मुसलमान बचपन से जानता है और अब जिन पर ठहरकर सोचने की ज़रूरत नहीं; हो सकता है उसके शब्द याद हों, लेकिन उसके डर, आशा और फ़ैसलों पर उनका असर न रह गया हो।",
            "quote_bindings": []
          },
          {
            "id": "p05.s05",
            "arabic": "ويبدأ هذا التعريف بأمر: ﴿قُلْ﴾.",
            "hindi": "यह परिचय एक आदेश से शुरू होता है: «आप कह दीजिए»।",
            "quote_bindings": [
              "Q:4"
            ]
          },
          {
            "id": "p05.s06",
            "arabic": "وقد بلّغ النبي ﷺ السورة كما أوحيت إليه، حتى كلمة الأمر نفسها؛ فلم يقل من عنده وصفًا لله، ولم يُسقط من الوحي ما تلقاه.",
            "hindi": "नबी ﷺ ने यह सूरा ठीक उसी तरह पहुँचाई जिस तरह वह आप पर उतरी थी, यहाँ तक कि आदेश का यह शब्द भी; आपने अपनी ओर से अल्लाह का कोई वर्णन नहीं गढ़ा और न मिली हुई वह्य का कोई हिस्सा छोड़ा।",
            "quote_bindings": []
          },
          {
            "id": "p05.s07",
            "arabic": "وفي إبقاء هذا الأمر تنبيه إلى أن التوحيد يُتعلَّم ويُبلَّغ، لا أن يبقى معرفة خاصة يكتمها صاحبها.",
            "hindi": "इस आदेश को बनाए रखने में यह सीख भी है कि तौहीद का ज्ञान सीखा और आगे पहुँचाया जाता है; वह किसी की निजी जानकारी बनकर नहीं रहना चाहिए जिसे वह छिपाए रखे।",
            "quote_bindings": []
          },
          {
            "id": "p05.s08",
            "arabic": "يتلقى المسلم ما عرّفه الله به عن نفسه، ثم يعلّمه غيره بالوضوح الذي جاء به القرآن، دون أن يجعل الألفاظ المعقدة والجدال حجابًا بين الناس وبين هذه الحقيقة.",
            "hindi": "मुसलमान अल्लाह के बारे में वही बात ग्रहण करता है जो अल्लाह ने स्वयं बताई है, फिर उसे क़ुरआन की तरह साफ़ ढंग से दूसरों को सिखाता है; कठिन शब्दों और बहस को लोगों और इस सच्चाई के बीच पर्दा नहीं बनाता।",
            "quote_bindings": []
          },
          {
            "id": "p05.s09",
            "arabic": "وقيل إن ﴿هُوَ﴾ ضمير الشأن؛ أي إن الكلام يهيئ السامع لخبر عظيم ينبغي أن يصغي إليه: الله أحد.",
            "hindi": "एक व्याख्या के अनुसार आयत में «वह» उस बड़े विषय की ओर ध्यान दिलाने वाला सर्वनाम है जिसकी ख़बर आगे दी जा रही है; यानी सुनने वाला एक महान बात पर कान लगाए: अल्लाह एक है।",
            "quote_bindings": [
              "Q:5"
            ]
          },
          {
            "id": "p05.s10",
            "arabic": "واسم «الله» عَلَم على ربنا سبحانه، ثم تأتي «أحد» لتقرر انفراده؛ فهو أحد في ذاته وصفاته وأفعاله، لا شريك له في شيء من ذلك.",
            "hindi": "‘अल्लाह’ हमारे पवित्र रब का विशेष नाम है, और उसके बाद ‘अहद’ उसकी अद्वितीयता स्पष्ट करता है; वह अपने अस्तित्व, गुणों और कर्मों में एक और बेजोड़ है, इनमें कोई उसका साझी नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p05.s11",
            "arabic": "ومن وجوه التفريق التي قيلت بين «الواحد» و«الأحد» أن الأحدية هنا لا يراد بها مجرد عدّ واحد في مقابل اثنين، بل الانفراد الذي لا نظير معه في كمال الذات والصفات والأفعال.",
            "hindi": "‘वाहिद’ और ‘अहद’ के बीच बताए गए अंतरों में से एक यह है कि यहाँ एक होने से केवल गिनती का एक अभिप्रेत नहीं, जो दो के मुक़ाबले में आता है; बल्कि अस्तित्व, गुणों और कर्मों की पूर्णता में ऐसी अद्वितीयता है जिसका कोई समकक्ष नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p05.s12",
            "arabic": "ولكي لا يبقى هذا المعنى كلامًا مجردًا، تأمل ما قرأته في القرآن عن أفعال الله.",
            "hindi": "इस बात को केवल एक अमूर्त विचार बनकर न रह जाने दें; क़ुरआन में अल्लाह के कर्मों के बारे में जो पढ़ा है, उस पर ग़ौर कीजिए।",
            "quote_bindings": []
          },
          {
            "id": "p05.s13",
            "arabic": "أنت ترى من ينجي من الهلاك، وينصر المظلوم، ويهلك الظالم، ويشفي المريض، ويهدي الضال؛ ﴿كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ﴾ [الرحمن: 29].",
            "hindi": "आप देखते हैं कि विनाश से कौन बचाता है, अत्याचार सहने वाले की मदद कौन करता है, अत्याचारी को कौन मिटाता है, रोगी को कौन स्वस्थ करता है और भटके हुए को कौन राह दिखाता है: «वह प्रतिदिन एक (नए) कार्य में है।[3]»",
            "quote_bindings": [
              "Q:10"
            ]
          },
          {
            "id": "p05.s14",
            "arabic": "فإذا بلغت هذه السورة قرب ختام المصحف فكأنها تجيب سؤالًا تحرك في قلبك: من الذي فعل ذلك كله؟ هو الله أحد.",
            "hindi": "फिर जब आप क़ुरआन के अंत के क़रीब इस सूरा तक पहुँचते हैं, तो मानो यह आपके दिल में उठे सवाल का जवाब देती है: यह सब किसने किया? वही अल्लाह है, जो एक और बेजोड़ है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s15",
            "arabic": "فالذي أنجى إبراهيم من النار هو الله؛ وقد قال إبراهيم حين ألقي فيها: «حسبنا الله ونعم الوكيل» [البخاري: 4563]، وجاء الأمر الإلهي: ﴿يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ﴾ [الأنبياء: 69].",
            "hindi": "इब्राहीम अलैहिस्सलाम को आग से बचाने वाला अल्लाह ही है; आग में डाले जाने पर इब्राहीम अलैहिस्सलाम ने कहा था: «हमारे लिए अल्लाह काफ़ी है, और वह सबसे अच्छा काम बनाने वाला है।» और अल्लाह का आदेश आया: «ऐ आग! तू इबराहीम पर ठंडक और सुरक्षा सुरक्षा बन जा।»",
            "quote_bindings": [
              "N:12",
              "Q:14"
            ]
          },
          {
            "id": "p05.s16",
            "arabic": "والذي صرف عن يوسف كيد النساء هو الله؛ فقد قال يوسف: ﴿وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ﴾، فاستجاب له ربه وصرف عنه كيدهن [يوسف: 33–34].",
            "hindi": "यूसुफ़ अलैहिस्सलाम से औरतों की चाल दूर करने वाला भी अल्लाह ही है; यूसुफ़ अलैहिस्सलाम ने कहा था: «और यदि तूने मुझसे इनके छल को दूर नहीं किया, तो मैं इनकी ओर झुक जाऊँगा»। तब उनके रब ने उनकी दुआ क़बूल की और उनसे उन औरतों की चाल दूर कर दी।",
            "quote_bindings": [
              "Q:16"
            ]
          },
          {
            "id": "p05.s17",
            "arabic": "والذي سمع يونس في ظلمات بطن الحوت وأنجاه هو الله؛ ناداه: ﴿لَا إِلَٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ﴾، فجاء الجواب: ﴿فَاسْتَجَبْنَا لَهُ وَنَجَّيْنَاهُ مِنَ الْغَمِّ﴾ [الأنبياء: 87–88].",
            "hindi": "मछली के पेट के अंधेरों में यूनुस अलैहिस्सलाम की पुकार सुनकर उन्हें बचाने वाला भी अल्लाह ही है; उन्होंने उसे पुकारा: «तेरे सिवा कोई पूज्य नहीं, तू पवित्र है। निश्चय मैं ही अत्याचारियों में हो गया।[36]» तब जवाब आया: «तो हमने उनकी दुआ क़बूल की तथा उन्हें शोक से मुक्त कर दिया।»",
            "quote_bindings": [
              "Q:18",
              "Q:19"
            ]
          },
          {
            "id": "p05.s18",
            "arabic": "تختلف الشدائد: نار، وفتنة، وغم في الظلمات، لكن الذي يملك النجاة منها واحد.",
            "hindi": "कठिनाइयाँ अलग-अलग हैं: कहीं आग है, कहीं पाप की ओर खिंचाव, कहीं अंधेरों में ग़म; मगर इन सब से बचाने का अधिकार एक ही के पास है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s19",
            "arabic": "وتتكرر هذه المعرفة حين تقرأ خبر إغراق فرعون، أو لطف الله بيوسف في سجنه، أو نصر المؤمنين ببدر مع ضعفهم: ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ﴾ [آل عمران: 123]؛ فتتنوع أفعال الرب الواحد، ويعرفه عبده من خلال القصص كما يعرفه من الآيات التي تصف أسماءه وصفاته.",
            "hindi": "यही पहचान तब भी ताज़ा होती है जब आप फ़िरऔन के डूबने, क़ैद में यूसुफ़ अलैहिस्सलाम पर अल्लाह की कोमल कृपा, या कमज़ोरी के बावजूद बद्र में ईमान वालों को मिली मदद का वृत्तांत पढ़ते हैं: «और अल्लाह बद्र (के युद्ध) में तुम्हारी सहायता कर चुका है, जबकि तुम कमज़ोर थे।» एक ही रब के कर्म अलग-अलग रूपों में सामने आते हैं, और बंदा इन वृत्तांतों से भी उसे पहचानता है, जैसे उन आयतों से पहचानता है जो उसके नाम और गुण बताती हैं।",
            "quote_bindings": [
              "Q:21"
            ]
          },
          {
            "id": "p05.s20",
            "arabic": "فإذا اشتاق قلبك إلى لطفه ورحمته، فقد عرفت إلى من تتجه، ويأتي بعد ذلك قوله: ﴿اللَّهُ الصَّمَدُ﴾.",
            "hindi": "जब आपका दिल उसकी कृपा और दया का इच्छुक हो, तो आप जान चुके होते हैं कि किस ओर रुख़ करना है; इसके बाद उसका यह कथन आता है: «अल्लाह बेनियाज़ है।»",
            "quote_bindings": [
              "Q:23"
            ]
          },
          {
            "id": "p05.s21",
            "arabic": "ومن هنا يُفهم عِظَم هذه السورة مع قصرها؛ قال النبي ﷺ: «قل هو الله أحد تعدل ثلث القرآن» [مسلم: 811].",
            "hindi": "यहीं से इस छोटी-सी सूरा की महानता समझ आती है; नबी ﷺ ने सूरा इख़लास के बारे में फ़रमाया: «यह सूरा एक तिहाई क़ुरान के समान है।»",
            "quote_bindings": [
              "N:24"
            ]
          },
          {
            "id": "p05.s22",
            "arabic": "قد يتوقع السامع أن تكون السورة التي تبلغ هذه المنزلة طويلةً، فإذا بها أربع آيات؛ فيتنبه إلى قدر المعنى الذي اجتمعت عليه، لا إلى عدد كلماتها وحده.",
            "hindi": "सुनने वाला शायद सोचे कि इतने ऊँचे दर्जे वाली सूरा लंबी होगी, लेकिन यह तो चार आयतें हैं; इससे ध्यान केवल शब्दों की संख्या पर नहीं, उस महान अर्थ की महत्ता पर जाता है जिसे यह सूरा समेटे हुए है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s23",
            "arabic": "ويؤكد هذا المعنى ما جرى لأُبيّ بن كعب حين سأله النبي ﷺ عن أعظم آية في كتاب الله، فذكر آية الكرسي، فأقره النبي ﷺ وهنّأه بالعلم [مسلم: 810].",
            "hindi": "इसी बात की पुष्टि उबय बिन कअब रज़ियल्लाहु अन्हु के प्रसंग से होती है: नबी ﷺ ने उनसे अल्लाह की किताब की सबसे महान आयत पूछी तो उन्होंने आयतुल कुर्सी का उल्लेख किया; आपने उनके उत्तर को सही बताया और इस ज्ञान पर उन्हें बधाई दी।",
            "quote_bindings": []
          },
          {
