            "arabic": "إنها آية تعرف بالله وعلمه وقيوميته وملكه.",
            "hindi": "यह आयत अल्लाह, उसके ज्ञान और बादशाही का परिचय देती है, और बताती है कि वह स्वयं किसी पर निर्भर नहीं और सब उसी के सहारे बने हुए हैं।",
            "quote_bindings": []
          },
          {
            "id": "p05.s25",
            "arabic": "وكذلك الفاتحة، التي أخبر النبي ﷺ أنها أعظم سورة في القرآن، تجمع الثناء على الله وطلب الهداية منه [البخاري: 4474].",
            "hindi": "इसी तरह फ़ातिहा, जिसे नबी ﷺ ने क़ुरआन की सबसे महान सूरा बताया, अल्लाह की प्रशंसा और उससे मार्गदर्शन की प्रार्थना को एक साथ लाती है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s26",
            "arabic": "فالبحث عن هداية القرآن لا يصح أن يتجاوز هذه المعاني الواضحة إلى اللطائف الدقيقة وحدها؛ من التدبر أن يعود معنى مألوف إلى قلبك حيًّا مؤثرًا بعد أن اعتدت ترديده.",
            "hindi": "क़ुरआन से मार्गदर्शन पाने की कोशिश में इन स्पष्ट अर्थों को पार करके केवल बारीक बातों की खोज में लग जाना ठीक नहीं; मनन यह भी है कि जिस परिचित अर्थ को आप आदतन दोहराने लगे थे, वह फिर से दिल में जीवंत हो और असर करे।",
            "quote_bindings": []
          },
          {
            "id": "p05.s27",
            "arabic": "وحتى الآيات التي سمعها نفر من الجن حملتهم على إعلان الإيمان ونفي الشرك: ﴿يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا﴾ [الجن: 2]؛ فثمرة السماع ليست الإعجاب بالكلام فحسب، بل معرفة المعبود وإخلاص العبادة له.",
            "hindi": "जिन्नों के एक समूह ने भी जो आयतें सुनीं, उन्होंने उन्हें ईमान का एलान करने और शिर्क से इनकार करने के लिए प्रेरित किया: «जो सीधी राह दिखाता है, तो हम उसपर ईमान ले आए और (अब) हम अपने पालनहार के साथ किसी को कभी साझी नहीं बनाएँगे।» सुनने का फल केवल वाणी से प्रभावित होना नहीं, बल्कि अपने पूज्य को पहचानकर केवल उसी की इबादत करना है।",
            "quote_bindings": [
              "Q:28"
            ]
          },
          {
            "id": "p05.s28",
            "arabic": "وهذه العبادة حق لله على خلقه، لا قضية هامشية تزاحمها سائر الاهتمامات حتى تُنسى.",
            "hindi": "यह इबादत सृष्टि पर अल्लाह का अधिकार है; कोई गौण बात नहीं जिसे दूसरी व्यस्तताओं की भीड़ में भुला दिया जाए।",
            "quote_bindings": []
          },
          {
            "id": "p05.s29",
            "arabic": "فقد بيّن النبي ﷺ لمعاذ أن حق الله على العباد «أن يعبدوه ولا يشركوا به شيئًا» [البخاري: 2856].",
            "hindi": "नबी ﷺ ने मुआज़ रज़ियल्लाहु अन्हु को बंदों पर अल्लाह का अधिकार यह बताया: «बंदों पर अल्लाह का अधिकार यह है कि बंदे उसकी इबादत करें और किसी को उसका साझी न बनाएँ।»",
            "quote_bindings": [
              "N:30"
            ]
          },
          {
            "id": "p05.s30",
            "arabic": "وقد ينشغل الناس طويلًا بحقوق بعضهم على بعض، ثم يغفلون عن حق من خلقهم جميعًا؛ فتردهم الآية إلى هذا الأصل.",
            "hindi": "लोग कभी एक-दूसरे के अधिकारों में बहुत समय लगाते हैं, फिर उन सबको पैदा करने वाले के अधिकार से ग़ाफ़िल हो जाते हैं; यह आयत उन्हें इसी बुनियाद की ओर लौटाती है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s31",
            "arabic": "وليس الإقرار به مجرد عبارة لا يترتب عليها شيء؛ كان بلال رضي الله عنه يقول وهو يعذَّب: «أحدٌ أحدٌ» [ابن ماجه: 150].",
            "hindi": "इसका स्वीकार कर लेना केवल ऐसे शब्द कहना नहीं जिनका कोई नतीजा न निकले; बिलाल रज़ियल्लाहु अन्हु यातना सहते हुए कहते थे: «अल्लाह एक है, अल्लाह एक है।»",
            "quote_bindings": [
              "N:32"
            ]
          },
          {
            "id": "p05.s32",
            "arabic": "كانوا يملكون إيذاء جسده، لكنه لم يجعل لهم سلطانًا يبدل به معبوده؛ فالكلمة تعلن لمن تكون عبوديته، ولهذا كانت ثقيلة على من أرادوا صرفه عن دينه.",
            "hindi": "वे लोग उनके शरीर को कष्ट पहुँचा सकते थे, मगर बिलाल रज़ियल्लाहु अन्हु ने उन्हें अपने पूज्य को बदल देने का अधिकार नहीं दिया; यह शब्द घोषित करता था कि उनकी बंदगी किसके लिए है, इसलिए उन्हें उनके दीन से फेरना चाहने वालों पर वह भारी पड़ता था।",
            "quote_bindings": []
          },
          {
            "id": "p05.s33",
            "arabic": "وتذكر السيرة أن «أحدٌ أحدٌ» كانت أيضًا شعار المسلمين يوم بدر [ابن هشام، السيرة النبوية، خبر شعار المسلمين يوم بدر].",
            "hindi": "सीरत में यह भी मिलता है कि बद्र के दिन मुसलमानों की पहचान का नारा भी यही था: «अल्लाह एक है, अल्लाह एक है।»",
            "quote_bindings": [
              "N:34"
            ]
          },
          {
            "id": "p05.s34",
            "arabic": "فالمعنى الذي ثبّت المؤمن في الاستضعاف هو نفسه الذي يحمله في حال القوة، لا عقيدة يتركها إذا اشتدت عليه المحنة أو استغنى بشيء من الدنيا.",
            "hindi": "जिस सच्चाई ने कमज़ोरी के समय ईमान वाले को अडिग रखा, वही ताक़त के समय भी उसके साथ रहती है; यह ऐसा विश्वास नहीं जिसे कठिन परीक्षा आने या दुनिया की कुछ समृद्धि मिलने पर छोड़ दिया जाए।",
            "quote_bindings": []
          },
          {
            "id": "p05.s35",
            "arabic": "ولأن القلب يخالط الناس والأسباب كل يوم، وتتوزعه مشاعر الخوف والرجاء والحرص، فإنه يحتاج إلى تجديد هذه المعرفة، لا إلى سماعها مرة ثم الانصراف عنها.",
            "hindi": "दिल रोज़ लोगों और साधनों से जुड़ता है, और डर, आशा तथा कुछ पाने की चाह उसे अलग-अलग ओर खींचती हैं; इसलिए उसे इस पहचान को ताज़ा करने की ज़रूरत है, केवल एक बार सुनकर आगे बढ़ जाना काफ़ी नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p05.s36",
            "arabic": "ولهذا شُرع تكرار التهليل: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير» مائة مرة في اليوم [البخاري: 3293].",
            "hindi": "इसीलिए दिन में सौ बार तौहीद का यह कलिमा पढ़ने की शिक्षा दी गई है, जिसका अर्थ है: «अल्लाह के सिवा कोई इबादत के लायक़ नहीं। वह अकेला है। उसका कोई शरीक नहीं। बादशाही उसी की है। उसी के लिए सब तारीफ़ है।» «और वह हर चीज़ पर क़ुदरत रखने वाला है।»",
            "quote_bindings": [
              "N:36:1",
              "N:36:2"
            ]
          },
          {
            "id": "p05.s37",
            "arabic": "الكلمات معروفة، لكن تكرارها يرد القلب إلى من يملك الأمر حين يكاد ينشغل عنه بما حوله.",
            "hindi": "शब्द परिचित हैं, लेकिन उन्हें दोहराना दिल को उस हस्ती की ओर लौटाता है जिसके हाथ में सारा अधिकार है, जब आस-पास की चीज़ें उसे उससे ग़ाफ़िल करने लगती हैं।",
            "quote_bindings": []
          },
          {
            "id": "p05.s38",
            "arabic": "وفي فضل الإخلاص ما يرغب في إكثار تلاوتها؛ فمن جهة ما تعدله من القرآن، يُرجى لقارئها ثلاث مرات ثواب قراءة القرآن.",
            "hindi": "सूरा इख़लास की फ़ज़ीलत उसे अधिक पढ़ने की प्रेरणा देती है; क़ुरआन के एक तिहाई के बराबर होने की दृष्टि से उसे तीन बार पढ़ने वाले के लिए पूरे क़ुरआन की तिलावत के सवाब की आशा की जाती है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s39",
            "arabic": "ثم تتجدد معانيها في الصلاة: كان النبي ﷺ يقرأ في الوتر بسورة الأعلى، ثم الكافرون، ثم الإخلاص [أبو داود: 1423]، ويقرأ في ركعتي سنة الفجر بالكافرون والإخلاص [مسلم: 726].",
            "hindi": "फिर नमाज़ में भी इसके अर्थ ताज़ा होते हैं: नबी ﷺ वित्र में पहले सूरा अल-आला, फिर अल-काफ़िरून और फिर इख़लास पढ़ते थे, और फ़ज्र की दो रकअत सुन्नत नमाज़ में अल-काफ़िरून और इख़लास पढ़ते थे।",
            "quote_bindings": []
          },
          {
            "id": "p05.s40",
            "arabic": "فتجتمع البراءة من عبادة غير الله في الكافرون، وإثبات التوحيد له في الإخلاص؛ ولهذا قيل عن الكافرون أيضًا إنها سورة إخلاص.",
            "hindi": "यों अल-काफ़िरून में अल्लाह के सिवा किसी की इबादत से अलग होने की घोषणा और इख़लास में उसकी तौहीद का स्वीकार एक साथ आते हैं; इसीलिए अल-काफ़िरून को भी इख़लास की सूरा कहा गया है।",
            "quote_bindings": []
          },
          {
            "id": "p05.s41",
            "arabic": "وفي هدوء الليل يراجع المؤمن يومه على هذه الحقيقة، مستعينًا بما لقيام الليل من أثر في موافقة اللسان للقلب: ﴿إِنَّ نَاشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئًا وَأَقْوَمُ قِيلًا﴾ [المزمل: 6]، ثم يبدأ يومه بتجديدها قبل أن يخرج إلى الناس.",
            "hindi": "रात की शांति में ईमान वाला इसी सच्चाई की रोशनी में अपने दिन की समीक्षा करता है और रात की नमाज़ से ज़बान और दिल में पैदा होने वाले मेल का सहारा लेता है: «निःसंदेह रात की इबादत हृदय में अधिक प्रभावी होती है और बात के लिए अधिक उपयुक्त होती है।» फिर लोगों के बीच निकलने से पहले अपना दिन इसी सच्चाई को ताज़ा करके शुरू करता है।",
            "quote_bindings": [
              "Q:40"
            ]
          },
          {
            "id": "p05.s42",
            "arabic": "ومن التدبر في هذا التكرار بين ظلمة الليل ونور الفجر أن التوحيد لا يتبدل مع تبدل الأحوال: تشتد الظروف أو تنفرج، ويضعف المؤمنون أو يقوون، ويبقى ربهم أحدًا وعبوديتهم له وحده؛ فلا تُغيَّر هذه الحقيقة طلبًا لمصلحة عارضة، وإنما تُراجع الأعمال والاختيارات على ضوئها.",
            "hindi": "रात के अंधेरे और फ़ज्र की रोशनी के बीच इस दोहराव पर ग़ौर करने से यह समझ आता है कि हालात बदलने पर तौहीद नहीं बदलती: परिस्थितियाँ कठिन हों या आसान, ईमान वाले कमज़ोर हों या ताक़तवर, उनका रब एक ही रहता है और उनकी बंदगी केवल उसी के लिए होती है; किसी अस्थायी लाभ के लिए इस सच्चाई को नहीं बदला जाता, बल्कि कर्मों और फ़ैसलों को उसकी रोशनी में परखा जाता है।",
            "quote_bindings": []
          }
        ]
      },
