            "arabic": "فكيف يعرف كمال ربه ثم يعلق قلبه بمن لا يملك لنفسه غنىً عنه؟ الصمد هو الذي تضع حاجتك بين يديه، وتتوجه إليه بكل ما في قلبك من افتقار ورجاء، سواء كنت تملك بعض أسباب قضائها أو لم تجد لها سببًا.",
            "hindi": "फिर अपने रब की पूर्णता जानकर उसका दिल ऐसी हस्ती से क्यों जुड़ जाए जो स्वयं भी उस रब से बेनियाज़ नहीं हो सकती? समद वह है जिसके सामने आप अपनी ज़रूरत रखते हैं और दिल की पूरी मोहताजी और आशा के साथ उसकी ओर रुख़ करते हैं, चाहे उसे पूरा करने के कुछ साधन आपके पास हों या कोई साधन न मिले।",
            "quote_bindings": []
          },
          {
            "id": "p08.s11",
            "arabic": "وليس ذلك سؤالًا باللسان مع بقاء القلب منصرفًا إلى غيره؛ بل تعلق حقيقي بمن تسأله.",
            "hindi": "यह केवल ज़बान से माँगना नहीं कि दिल किसी और ओर लगा रहे; बल्कि जिससे आप माँगते हैं, दिल का सच्चा लगाव भी उसी से हो।",
            "quote_bindings": []
          },
          {
            "id": "p08.s12",
            "arabic": "ولتقريب ما في هذا التعلق من شوق وافتقار، ذُكر في بعض الأقوال اللغوية قولهم: «أَلِهَ الفصيلُ إلى أمه»؛ والفصيل ولد الناقة بعد فطامه، إذا فُصل عنها اشتد حنينه إليها، حتى يصدر رغاءه كأنه يشكو أنه لا يطيق بعدها.",
            "hindi": "इस लगाव की तड़प और मोहताजी समझाने के लिए कुछ भाषागत मतों में एक उदाहरण दिया गया है: ऊँटनी का दूध छुड़ाया हुआ बच्चा अपनी माँ के लिए बेचैन हो उठा; माँ से अलग होने पर उसे इतनी याद आती है कि वह इस तरह बिलबिलाता है मानो कह रहा हो कि उससे दूर रहना सह नहीं सकता।",
            "quote_bindings": []
          },
          {
            "id": "p08.s13",
            "arabic": "وقد قيل بارتباط هذا المعنى باشتقاق اسم «الله»، وهو قول يُحكى، لا اشتقاق يُجزم به.",
            "hindi": "इस अर्थ का ‘अल्लाह’ नाम की शब्द-उत्पत्ति से संबंध बताया गया है, मगर यह एक वर्णित मत है; इस उत्पत्ति को निश्चित नहीं कहा जा रहा।",
            "quote_bindings": []
          },
          {
            "id": "p08.s14",
            "arabic": "والمقصود من الصورة تقريب حال القلب المتلهف، لا تشبيه الله بخلقه؛ فكما أن محبة الأم ليست هي محبة الصديق أو الولد، ففي القلب عبودية ومحبة وافتقار لا يصح أن تُصرف إلا لله.",
            "hindi": "उदाहरण का उद्देश्य दिल की तड़प समझाना है, अल्लाह को सृष्टि जैसा बताना नहीं; जैसे माँ से प्रेम, मित्र या संतान से प्रेम जैसा नहीं होता, उसी तरह दिल में बंदगी, प्रेम और मोहताजी का एक भाव है जिसे केवल अल्लाह के लिए होना चाहिए।",
            "quote_bindings": []
          },
          {
            "id": "p08.s15",
            "arabic": "ومن الإخلاص أن تعرف هذه المشاعر في نفسك، ثم تغذيها بذكر ربك وتوجهها إليه، بدل أن تستولي عليها المخلوقات والأسباب.",
            "hindi": "इख़लास का तक़ाज़ा है कि आप अपने भीतर इन भावों को पहचानें, अपने रब के ज़िक्र से उन्हें पोषित करें और उसी की ओर मोड़ें, बजाय इसके कि सृष्टि और साधन उन पर छा जाएँ।",
            "quote_bindings": []
          },
          {
            "id": "p08.s16",
            "arabic": "وترى هذا الاعتماد في قصة أم موسى حين جاءها الأمر: ﴿فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ﴾ [القصص: 7].",
            "hindi": "यही भरोसा मूसा अलैहिस्सलाम की माँ के प्रसंग में दिखता है, जब उन्हें आदेश मिला: «फिर जब तुझे उसके बारे में भय हो, तो उसे दरिया में डाल दे»।",
            "quote_bindings": [
              "Q:51"
            ]
          },
          {
            "id": "p08.s17",
            "arabic": "كانت تخاف على ابنها، فجاء نجاته في امتثال أمر الله، وإن بدا لها اليم موضع خوف؛ فالعبرة في هذا الموقف بثقتها بمن أمرها ووعدها، لا بمظهر الطريق وحده.",
            "hindi": "वे अपने बेटे के लिए डरी हुई थीं, लेकिन उसकी रक्षा अल्लाह के आदेश का पालन करने में हुई, भले ही दरिया उन्हें भय की जगह दिखाई देता था; इस प्रसंग में मूल बात उस पर उनका भरोसा है जिसने आदेश दिया और वादा किया, केवल रास्ते का बाहरी रूप नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p08.s18",
            "arabic": "وترى يقينًا من هذا الباب في موقف هود أمام قومه، حين قال: ﴿فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنْظِرُونِ﴾، ثم بيّن ما يستند إليه: ﴿إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُمْ﴾، وختم بقوله: ﴿إِنَّ رَبِّي عَلَىٰ صِرَاطٍ مُسْتَقِيمٍ﴾ [هود: 55–56].",
            "hindi": "ऐसा ही विश्वास हूद अलैहिस्सलाम के अपनी जाति के सामने खड़े होने में दिखता है, जब उन्होंने कहा: «अतः तुम सब मिलकर मेरे विरुद्ध चाल चलो, फिर मुझे मोहलत न दो।[16]» फिर अपने सहारे की बुनियाद बताई: «निःसंदेह मैंने अपने पालनहार और तुम्हारे पालनहार, अल्लाह पर भरोसा किया है।» और अंत में कहा: «निश्चय ही मेरा पालनहार सीधे रास्ते[17] पर है।»",
            "quote_bindings": [
              "Q:53",
              "Q:54",
              "Q:55"
            ]
          },
          {
            "id": "p08.s19",
            "arabic": "فهو يعرف قدرة ربه، ويطمئن إلى عدله وتدبيره؛ ومن أسمائه سبحانه «المؤمن»، فيأمن العبد من أن يظلمه ربه أو يخلف وعده.",
            "hindi": "वे अपने रब की शक्ति जानते हैं और उसके न्याय तथा प्रबंध पर संतुष्ट हैं; उसके नामों में ‘अल-मुमिन’ भी है, इसलिए बंदा इस आशंका से निश्चिंत रहता है कि उसका रब उस पर अत्याचार करेगा या अपना वादा तोड़ेगा।",
            "quote_bindings": []
          },
          {
            "id": "p08.s20",
            "arabic": "فلا يوازن بين نفسه وقوة قومه وهو ناسٍ لمن بيده أمر الجميع.",
            "hindi": "वे अपनी ताक़त का अपनी जाति की ताक़त से मुक़ाबला करते हुए उसे नहीं भूलते जिसके हाथ में सबका मामला है।",
            "quote_bindings": []
          },
          {
            "id": "p08.s21",
            "arabic": "ولهذا ترتبط معرفة التوحيد بالأمن، كما في قوله تعالى: ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُمْ مُهْتَدُونَ﴾ [الأنعام: 82].",
            "hindi": "इसीलिए तौहीद की पहचान का सुरक्षा से संबंध है, जैसा कि अल्लाह ने फ़रमाया: «जो लोग ईमान लाए और उन्होंने अपने ईमान को अत्याचार (शिर्क) के साथ नहीं मिलाया[57], यही लोग हैं जिनके लिए शांति है तथा वही मार्गदर्शन पाने वाले हैं।»",
            "quote_bindings": [
              "Q:58"
            ]
          },
          {
            "id": "p08.s22",
            "arabic": "وكما ترجع إلى الله في حاجتك، ترجع إلى وحيه لتعرف ما يرضيه وما يأمرك به؛ فليس معنى أن تصمد إليه أن تطلب عطاءه ثم تستغني عن هدايته في حياتك.",
            "hindi": "जैसे आप अपनी ज़रूरत में अल्लाह की ओर लौटते हैं, वैसे ही उसकी प्रसन्नता और उसके आदेश जानने के लिए उसकी वह्य की ओर लौटते हैं; उसकी ओर रुख़ करने का अर्थ यह नहीं कि उससे कुछ पाने की इच्छा करें, फिर अपने जीवन में उसके मार्गदर्शन से बेनियाज़ हो जाएँ।",
            "quote_bindings": []
          },
          {
            "id": "p08.s23",
            "arabic": "ولا يناقض هذا أن تسعى في الأسباب؛ فالله هو الذي أقام الحياة عليها.",
            "hindi": "साधन अपनाना इसके विरुद्ध नहीं, क्योंकि अल्लाह ने ही जीवन को साधनों पर स्थापित किया है।",
            "quote_bindings": []
          },
          {
            "id": "p08.s24",
            "arabic": "من أراد ثمرة حرث الأرض، وغرس البذرة، وتعاهدها بالسقي والرعاية؛ ولم يجعل الله الطريق المعتاد إلى الثمرة أن يترك الإنسان الزرع ويطلب نزولها من السماء.",
            "hindi": "जिसे उपज चाहिए, वह ज़मीन जोतता, बीज बोता और पानी देकर उसकी देखभाल करता है; अल्लाह ने उपज पाने का सामान्य रास्ता यह नहीं रखा कि मनुष्य खेती छोड़ दे और आकाश से उपज उतर आने की प्रार्थना करे।",
            "quote_bindings": []
          },
          {
            "id": "p08.s25",
            "arabic": "ومن مرض بحث عن الدواء وتداوى؛ وقد قال النبي ﷺ: «ما أنزل الله داء إلا أنزل له شفاء» [البخاري: 5678].",
            "hindi": "बीमार व्यक्ति दवा ढूँढता और इलाज करता है; नबी ﷺ ने फ़रमाया: «अल्लाह महिमावान ने कोई बीमारी नहीं भेजी, परंतु उसने उसके लिए एक इलाज भेजा है।»",
            "quote_bindings": [
              "N:60"
            ]
          },
          {
            "id": "p08.s26",
            "arabic": "لكن المريض وهو يتداوى لا ينسى أن الشفاء من الله، ولهذا يجمع سعيه مع الدعاء: «اشفه وأنت الشافي، لا شفاء إلا شفاؤك» [البخاري: 5743].",
            "hindi": "लेकिन इलाज करते हुए भी रोगी यह नहीं भूलता कि स्वस्थ करने वाला अल्लाह है, इसलिए अपनी कोशिश के साथ यह दुआ भी करता है: «रोग से मुक्ति प्रदान कर, तू ही रोग से मुक्ति प्रदान करने वाला  है। तेरे सिवा कोई रोग से मुक्ति प्रदान करने वाला नहीं है।»",
            "quote_bindings": [
              "N:62"
            ]
          },
          {
            "id": "p08.s27",
            "arabic": "وكذلك يسعى إلى الرزق ولا يجعل العمل رازقًا مستقلًا، ويأخذ بأسباب النصر وهو يوقن بأن ﴿وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ﴾ [الأنفال: 10].",
            "hindi": "इसी तरह वह रोज़ी के लिए काम करता है, लेकिन काम को अपने आप में रोज़ी देने वाला नहीं मानता; विजय के साधन अपनाता है, मगर विश्वास रखता है कि «सहायता तो अल्लाह ही की ओर से होती है।»",
            "quote_bindings": [
              "Q:64"
            ]
          },
          {
            "id": "p08.s28",
            "arabic": "فالخلل ليس في مباشرة السبب، وإنما في أن يغيب رب السبب عن القلب، حتى يصبح خوف الإنسان ورجاؤه معلقين بالأداة وحدها.",
            "hindi": "ख़राबी साधन अपनाने में नहीं, बल्कि इस बात में है कि साधन के रब का ध्यान दिल से निकल जाए, यहाँ तक कि मनुष्य का डर और उसकी आशा केवल साधन से जुड़ जाएँ।",
            "quote_bindings": []
          },
          {
            "id": "p08.s29",
            "arabic": "وقد تثمر الأسباب، وقد تتخلف نتائجها، وقد يقع خلاف ما توقعه صاحبها؛ فإذا كان تعلقه بالله من البداية لم تنقطع صلته به حين تتعطل وسيلة من وسائله.",
            "hindi": "साधन सफल भी हो सकते हैं, कभी उनका नतीजा नहीं निकलता और कभी अपेक्षा के विपरीत कुछ हो जाता है; यदि शुरू से उसका लगाव अल्लाह से है, तो किसी साधन के विफल होने पर भी अल्लाह से उसका संबंध नहीं टूटता।",
            "quote_bindings": []
          },
          {
            "id": "p08.s30",
            "arabic": "ومن وراء ما على الأرض من زينة تستغرق النظر [الكهف: 7]، تبقى حقيقة أن تدبير الأمور كله لله؛ فهو ﴿الْأَوَّلُ وَالْآخِرُ﴾ [الحديد: 3]، فلا يبدأ سبب مستقلًا عنه، ولا تنتهي نتيجة إلى سلطان خارج عن سلطانه.",
            "hindi": "धरती की वह सारी सजावट, जो निगाहों को बाँध लेती है, अपनी जगह; उसके पीछे सच्चाई यही रहती है कि सभी मामलों का प्रबंध अल्लाह के हाथ में है; उसी के बारे में कहा गया है: «वही सबसे पहले है और सबसे आख़िर है»। कोई साधन उससे स्वतंत्र होकर शुरू नहीं होता और कोई नतीजा उसके अधिकार से बाहर किसी अधिकार के अधीन नहीं जाता।",
            "quote_bindings": [
              "Q:67"
            ]
          },
          {
            "id": "p08.s31",
            "arabic": "وقد ظهر اجتماع حسن التدبير وكمال التوكل في الهجرة: أعد النبي ﷺ أسباب الطريق والدلالة والزاد [البخاري: 3905]، ثم بلغ المطاردون من الغار مبلغًا قال معه أبو بكر رضي الله عنه: لو أن أحدهم نظر تحت قدميه لأبصرنا.",
            "hindi": "हिजरत में अच्छा प्रबंध और पूरा भरोसा एक साथ दिखाई देते हैं: नबी ﷺ ने रास्ते, मार्गदर्शक और भोजन की तैयारी की, फिर पीछा करने वाले गुफा के इतने क़रीब आ गए कि अबू बक्र रज़ियल्लाहु अन्हु ने कहा: इनमें से कोई अपने पैरों के नीचे देख ले तो हमें देख लेगा।",
            "quote_bindings": []
          },
          {
            "id": "p08.s32",
            "arabic": "لم يكن جواب النبي ﷺ تعداد الاحتياطات التي أُخذت، بل قال: «ما ظنك يا أبا بكر باثنين الله ثالثهما» [البخاري: 3653]؛ وكذلك أخبر القرآن عن قوله لصاحبه: ﴿لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا﴾ [التوبة: 40].",
            "hindi": "नबी ﷺ ने जवाब में बरती गई सावधानियाँ नहीं गिनाईं, बल्कि फ़रमाया: «ऐ अबू बक्र, उन दो लोगों के बारे में तुम्हारा क्या ख़याल है, जिनका तीसरा अल्लाह है?» और क़ुरआन ने भी बताया है कि आपने अपने साथी से कहा था: «शोकाकुल न हो। निःसंदेह अल्लाह हमारे साथ है।[21]»",
            "quote_bindings": [
              "N:70",
              "Q:72"
            ]
          },
          {
            "id": "p08.s33",
            "arabic": "فالثقة بالله لم تبدأ بعد نفاد الحيلة؛ كانت معه قبل السعي وفي أثنائه وعند اشتداد الخطر.",
            "hindi": "अल्लाह पर भरोसा तब शुरू नहीं हुआ जब सारी युक्तियाँ ख़त्म हो गईं; वह कोशिश से पहले, उसके दौरान और ख़तरा बढ़ जाने पर भी आपके साथ था।",
            "quote_bindings": []
          },
          {
            "id": "p08.s34",
            "arabic": "وتكشف المعجزات أيضًا أن المألوف من الأسباب ليس قيدًا على قدرة الله: تنقلب العصا حية، وينفلق البحر، ويحيي عيسى الموتى بإذن الله.",
            "hindi": "चमत्कार भी बताते हैं कि परिचित साधन अल्लाह की शक्ति पर पाबंदी नहीं हैं: लाठी साँप बन जाती है, समुद्र फट जाता है और ईसा अलैहिस्सलाम अल्लाह की अनुमति से मुर्दों को जीवित कर देते हैं।",
            "quote_bindings": []
          },
          {
            "id": "p08.s35",
            "arabic": "هذه الآيات تخرج الإنسان من وهم أن ما اعتاده هو كل الممكن.",
