            "hindi": "इसीलिए अल्लाह के सुंदर नामों की पहचान के लिए उनके अर्थों को जीवन में महसूस करना ज़रूरी है, केवल उनकी परिभाषाएँ याद करना नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p08.s44",
            "arabic": "يقرأ الإنسان قصة يوسف فيرى لطف الله به خلال الأحداث، فيجد لمعنى «اللطيف» أثرًا لا يجده في عبارة جامدة منفصلة عن الحياة.",
            "hindi": "मनुष्य यूसुफ़ अलैहिस्सलाम का वृत्तांत पढ़ता है और घटनाओं के बीच उन पर अल्लाह की कोमल कृपा देखता है, तो ‘अल-लतीफ़’ के अर्थ का ऐसा प्रभाव पाता है जो जीवन से कटी हुई निर्जीव परिभाषा में नहीं मिलता।",
            "quote_bindings": []
          },
          {
            "id": "p08.s45",
            "arabic": "وقد يسمع عن غنى الله وكرمه، ثم تمر به حاجة يتوجه فيها إليه، فيعرف من أثر هذا الاسم في قلبه ما لم يجده عند مجرد سماعه.",
            "hindi": "कभी वह अल्लाह की बेनियाज़ी और उदारता के बारे में सुनता है, फिर अपनी किसी ज़रूरत में उसकी ओर रुख़ करता है, तो उसे अपने दिल पर उस नाम के असर का वह अनुभव होता है जो केवल सुन लेने से नहीं हुआ था।",
            "quote_bindings": []
          },
          {
            "id": "p08.s46",
            "arabic": "لكن كثرة التعامل مع المعاني العظيمة قد تتحول إلى عادة تُضعف التأثر بها: فقد يزور إنسان مريضًا فيرق قلبه ويتذكر نعمة العافية، بينما يألف بعض العاملين في المستشفى تكرر مشاهد المرض والموت، حتى يحتاجوا إلى تجديد الاعتبار بها؛ وقد يشتاق القادم إلى الحرم ويبكي حين يبلغه، بينما يحتاج بعض من اعتاد العمل فيه إلى مجاهدة الألفة حتى لا تحجبه عن عظم المكان.",
            "hindi": "लेकिन महान अर्थों से बार-बार वास्ता पड़ना ऐसी आदत भी बन सकता है जो उनका असर कम कर दे: कोई रोगी से मिलने जाए तो उसका दिल नरम होता है और उसे स्वास्थ्य की नेमत याद आती है, जबकि अस्पताल में काम करने वाले कुछ लोग बीमारी और मृत्यु के बार-बार दिखने के अभ्यस्त हो जाते हैं और उन्हें उनसे सीख लेने का भाव ताज़ा करना पड़ता है; कोई हरम पहुँचने को तड़पता है और पहुँचकर रो पड़ता है, जबकि वहाँ रोज़ काम करने वाले कुछ लोगों को इस अभ्यस्त हो जाने से संघर्ष करना पड़ता है ताकि यह आदत उस स्थान की महानता को उनकी नज़र से ओझल न कर दे।",
            "quote_bindings": []
          },
          {
            "id": "p08.s47",
            "arabic": "والمقصود أثر الاعتياد، لا الحكم على مهنة أو على قلوب أصحابها.",
            "hindi": "उद्देश्य आदत का प्रभाव बताना है, किसी पेशे या उससे जुड़े लोगों के दिलों पर फ़ैसला सुनाना नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p08.s48",
            "arabic": "وكذلك من طال حديثه عن الله في مناقشات مجردة، ثم قل نصيبه من الخشوع والافتقار، يحتاج إلى أن يعود إلى القرآن متلقيًا حديثه عن ربه، لا مكتفيًا بتحليل الألفاظ؛ فالذي خلقه أعلم بما يخاطب به قلبه: ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾ [الملك: 14].",
            "hindi": "इसी तरह जो अल्लाह के बारे में अमूर्त बहसें बहुत करता है, लेकिन उसके भीतर विनम्रता और मोहताजी कम हो गई है, उसे क़ुरआन की ओर लौटकर अपने रब के बारे में उसकी बात ग्रहण करनी चाहिए, केवल शब्दों का विश्लेषण करके संतुष्ट नहीं हो जाना चाहिए; जिसने उसे पैदा किया है, वह बेहतर जानता है कि उसके दिल को कैसे संबोधित करे: «क्या वह नहीं जानेगा जिसने पैदा किया?! जबकि वह सूक्ष्मदर्शी[5], पूर्ण ख़बर रखने वाला है।»",
            "quote_bindings": [
              "Q:87"
            ]
          },
          {
            "id": "p08.s49",
            "arabic": "ومن الدعاء الذي يجمع سؤال الله بأسمائه والانتفاع بكلامه أن يسأله العبد: «أن تجعل القرآن ربيع قلبي، ونور صدري، وجلاء حزني، وذهاب همي» [أحمد: 3712].",
            "hindi": "अल्लाह के नामों के सहारे उससे माँगने और उसकी वाणी से लाभ पाने को एक साथ लाने वाली एक वर्णित दुआ में बंदा यह माँगता है: «कि तू क़ुरआन को मेरे दिल की बहार और मेरे सीने का नूर बना दे,» «मेरे ग़म को दूर करने वाला और मेरी फ़िक्र को ले जाने वाला।»",
            "quote_bindings": [
              "N:89:1",
              "N:89:2"
            ]
          },
          {
            "id": "p08.s50",
            "arabic": "ولا يثبت هذا التوجه بسماع الموعظة وحده؛ فالعمل يغرس في القلب قدر ما يعمل له صاحبه.",
            "hindi": "केवल उपदेश सुनने से यह रुख़ दृढ़ नहीं होता; मनुष्य जिस उद्देश्य के लिए काम करता है, उसके प्रयास उस उद्देश्य की महत्ता दिल में बिठाते हैं।",
            "quote_bindings": []
