          },
          {
            "id": "p11.s12",
            "arabic": "فإذا كان هذا تصوير أثرها في السماوات والأرض والجبال، فكيف يمر المؤمن بها غير مبالٍ بحق ربه؟ إن تعظيم الله يقتضي أن ينزهه عن هذا القول ويعرف بطلانه، لا أن يألفه حتى يهون في قلبه.",
            "hindi": "जब आकाशों, धरती और पहाड़ों पर इस कथन के प्रभाव का यह चित्र हो, तो ईमान वाला इसे सुनकर अपने रब के अधिकार से बेपरवाह कैसे आगे बढ़ सकता है? अल्लाह की बड़ाई मानने का तक़ाज़ा है कि उसे इस बात से पवित्र माने और इस दावे का झूठा होना समझे, न कि सुनने का इतना अभ्यस्त हो जाए कि दिल में उसकी गंभीरता कम हो जाए।",
            "quote_bindings": []
          },
          {
            "id": "p11.s13",
            "arabic": "ويترتب على نفي النسب تصحيح طريق التوجه إلى الله.",
            "hindi": "अल्लाह के लिए वंश का निषेध उसकी ओर रुख़ करने का तरीक़ा भी सुधारता है।",
            "quote_bindings": []
          },
          {
            "id": "p11.s14",
            "arabic": "قد يحاول المرء الوصول إلى صاحب سلطان عن طريق أبيه أو ابنه، أو يظن أن قرابةً ما تملك أن تحمله على الاستجابة؛ أما الله فلا يُطلب رضاه على هذا المثال البشري.",
            "hindi": "मनुष्य कभी किसी शासक तक उसके पिता या बेटे के ज़रिए पहुँचने की कोशिश करता है, या समझता है कि कोई रिश्तेदार उसे बात मानने पर मजबूर कर सकता है; मगर अल्लाह की प्रसन्नता इस मानवीय उदाहरण के अनुसार नहीं माँगी जाती।",
            "quote_bindings": []
          },
          {
            "id": "p11.s15",
            "arabic": "ليس له أب ولا ابن يُتخذ طريقًا للضغط عليه أو لتحصيل ما لا يرضاه؛ فعبده يدعوه ويتوب إليه مباشرة.",
            "hindi": "न उसका कोई पिता है, न बेटा, जिसे उस पर दबाव डालने या उससे वह पाने का रास्ता बनाया जाए जो उसे पसंद नहीं; उसका बंदा सीधे उसी से दुआ करता और उसी के सामने तौबा करता है।",
            "quote_bindings": []
          },
          {
            "id": "p11.s16",
            "arabic": "وهذه راحة ورحمة للمذنب: لا يحتاج إلى أن يفضح ستره أمام إنسان ليمنحه المغفرة، ولا أن يحمل اعترافه إلى صنم أو إلى من يظنه صاحب سلطان على الله.",
            "hindi": "पाप करने वाले के लिए इसमें राहत और दया है: उसे क्षमा पाने के लिए किसी मनुष्य के सामने अपने छिपे पाप खोलने की ज़रूरत नहीं, न अपना पाप-स्वीकार किसी मूर्ति या ऐसी हस्ती के पास ले जाने की जिसे वह अल्लाह पर अधिकार रखने वाला मानता हो।",
            "quote_bindings": []
          },
          {
            "id": "p11.s17",
            "arabic": "قال موسى: ﴿رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي﴾، فأخبر الله: ﴿فَغَفَرَ لَهُ﴾ [القصص: 16].",
            "hindi": "मूसा अलैहिस्सलाम ने कहा: «ऐ मेरे पालनहार! निश्चय ही मैंने अपने ऊपर अत्याचार किया है, अतः मुझे क्षमा कर दे।» और अल्लाह ने बताया: «तो उसने उसे क्षमा कर दिया»।",
