          },
          {
            "id": "p14.s08",
            "arabic": "ونفي المكافئ ليس معلومة بعيدة عن حاجات القلب؛ إنه يقطع بحثه عن إله آخر يؤدي له ما يطلبه من الله، أو عن قوة تستطيع إلزام الله بما تريد.",
            "hindi": "उसका कोई बराबर न होना दिल की ज़रूरतों से दूर की जानकारी नहीं; यह किसी दूसरे पूज्य की खोज ख़त्म करता है जो उसे वह दे सके जो वह अल्लाह से माँगता है, या किसी ऐसी शक्ति की खोज जो अल्लाह को अपनी इच्छा मानने पर मजबूर कर सके।",
            "quote_bindings": []
          },
          {
            "id": "p14.s09",
            "arabic": "ولهذا تتتابع معاني السورة في اتجاه واحد: تعرف أنه أحد، فتصمد إليه، ثم تعلم أنه لا ولد له ولا والد ولا نظير، فلا تتشعب عبادتك بين جهات تتوهم لكل منها نصيبًا من تدبير أمرك.",
            "hindi": "इसीलिए सूरा के अर्थ एक ही दिशा में बढ़ते हैं: आप जान लेते हैं कि वह एक है, तो उसी की ओर रुख़ करते हैं, फिर जानते हैं कि न उसकी संतान है, न पिता, न कोई समकक्ष; यों आप इस गुमान में अपनी इबादत अलग-अलग दिशाओं में नहीं बाँटते कि प्रत्येक को आपके मामलों के प्रबंध में कुछ हिस्सा मिला है।",
            "quote_bindings": []
          },
          {
            "id": "p14.s10",
            "arabic": "ويبين القرآن أثر هذا التوحيد بمثل ﴿رَجُلًا فِيهِ شُرَكَاءُ مُتَشَاكِسُونَ وَرَجُلًا سَلَمًا لِرَجُلٍ﴾ [الزمر: 29]؛ الأول تتجاذبه إرادات متنازعة لا يكاد يرضي واحدة حتى تطالبه أخرى، والثاني يعرف لمن يعمل.",
            "hindi": "क़ुरआन तौहीद का प्रभाव एक उदाहरण से समझाता है; अल्लाह ने «एक व्यक्ति का उदाहरण दिया है, जिसमें कई परस्पर विरोधी साझी हैं तथा एक और व्यक्ति का, जो पूरा एक ही व्यक्ति का (दास) है।» पहले व्यक्ति को परस्पर लड़ती इच्छाएँ अलग-अलग ओर खींचती हैं; वह एक को ख़ुश करता ही है कि दूसरा माँग लेकर आ जाता है, जबकि दूसरा जानता है कि वह किसके लिए काम करता है।",
            "quote_bindings": [
              "Q:120"
            ]
          },
          {
            "id": "p14.s11",
            "arabic": "وكذلك القلب إذا علق خوفه ورجاءه بكل أحد وكل سبب تفرق وأُنهك؛ ومن رحمة الله أن أمره بعبادته وحده، لا بأن يحمل عبء إرضاء آلهة متعددة.",
            "hindi": "इसी तरह दिल अपना डर और अपनी आशा हर व्यक्ति और हर साधन से जोड़ ले तो बिखरकर थक जाता है; अल्लाह की दया है कि उसने केवल अपनी इबादत का आदेश दिया, कई पूज्यों को प्रसन्न करने का बोझ नहीं डाला।",
            "quote_bindings": []
          },
          {
            "id": "p14.s12",
            "arabic": "فيصير جمع الهم على الله طريقًا للخلاص من هذا التشتت، وتصبح معرفة التوحيد أساسًا للطاعة والطمأنينة والتحاكم إلى كتابه، لا قولًا منفصلًا عن الحياة.",
            "hindi": "यों अपना सारा ध्यान अल्लाह पर केंद्रित करना इस बिखराव से निकलने का रास्ता बनता है, और तौहीद की पहचान आज्ञापालन, सुकून और उसकी किताब के अनुसार फ़ैसला करने की बुनियाद बनती है; जीवन से कटी हुई बात नहीं रहती।",
            "quote_bindings": []
          },
          {
            "id": "p14.s13",
            "arabic": "ومن لطائف ترتيب خاتمة المصحف أن هذه المعرفة تليها الاستعاذة: ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ [الفلق: 1]، ثم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ [الناس: 1].",
            "hindi": "क़ुरआन की अंतिम सूरतों की व्यवस्था की एक सुंदर बात यह है कि इस पहचान के बाद शरण माँगना आता है: «(ऐ नबी!) कह दीजिए : मैं सुबह के पालनहार की शरण लेता हूँ।» फिर «(ऐ नबी!) कह दीजिए : मैं शरण लेता हूँ लोगों के पालनहार की।»",
            "quote_bindings": [
              "Q:122",
              "Q:124"
            ]
          },
          {
            "id": "p14.s14",
            "arabic": "فقد مر القارئ بأخبار الخلق ورأى ضعفهم، وبأخبار النجاة والنصر والرحمة وعرف من بيده ذلك كله؛ فإذا أيقن بالأحد الصمد، حمل إليه خوفه من الشرور.",
            "hindi": "पढ़ने वाला सृष्टि के वृत्तांतों से उसकी कमज़ोरी देख चुका है, और रक्षा, सहायता तथा दया के वृत्तांतों से जान चुका है कि यह सब किसके हाथ में है; इसलिए जब उसे अहद और समद का विश्वास हो जाता है, तो बुराइयों का डर लेकर उसी की ओर जाता है।",
            "quote_bindings": []
          },
          {
            "id": "p14.s15",
            "arabic": "فيستعيذ في الفلق من شر ما خلق، ومن شر الليل إذا دخل، ومن النفاثات في العقد ومن الحاسد، ويستعيذ في الناس من الوسواس الخناس الذي يفسد الصدر من داخله.",
            "hindi": "वह सूरा अल-फ़लक़ में सृष्टि की बुराई, छा जाने वाली रात की बुराई, गाँठों में फूँकने वालियों और ईर्ष्या करने वाले से शरण माँगता है, और सूरा अन-नास में उस वस्वसा डालने वाले, पीछे हट जाने वाले से शरण माँगता है जो सीने को भीतर से बिगाड़ता है।",
            "quote_bindings": []
          },
          {
            "id": "p14.s16",
            "arabic": "فهما ليستا انتقالًا إلى موضوع منفصل عن التوحيد؛ إنما تظهر فيهما ثمرة معرفته بمن لا كفء له.",
            "hindi": "इन दोनों सूरतों में बात तौहीद से अलग किसी विषय की ओर नहीं मुड़ती; इनमें उस हस्ती को पहचानने का फल दिखाई देता है जिसका कोई समकक्ष नहीं।",
            "quote_bindings": []
          },
          {
            "id": "p14.s17",
            "arabic": "وقد قال النبي ﷺ لعقبة بن عامر في المعوذتين: «تعوذ بهما فما تعوذ متعوذ بمثلهما» [أبو داود: 1463]؛ فيلجأ المؤمن إلى ربه بالكلمات التي علّمه إياها، وهو مستحضر لمعناها.",
            "hindi": "नबी ﷺ ने उक़्बा बिन आमिर रज़ियल्लाहु अन्हु से इन दोनों सूरतों के बारे में फ़रमाया: «इन दोनों से शरण माँगो; किसी शरण माँगने वाले ने इनके जैसी किसी चीज़ से शरण नहीं माँगी।» इसलिए ईमान वाला अपने रब के सिखाए हुए शब्दों से उसी की शरण लेता है और उनका अर्थ भी दिल में रखता है।",
            "quote_bindings": [
              "N:126"
            ]
          },
          {
            "id": "p14.s18",
            "arabic": "والتزام القرآن لا يعني أن صاحبه لن يُؤذى؛ فقد تعرض النبي ﷺ للكيد والحسد، وثبت ما أصابه من السحر [البخاري: 5765]، وجاء في شأن من اشتد غيظهم عند سماع الذكر: ﴿وَإِنْ يَكَادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ بِأَبْصَارِهِمْ لَمَّا سَمِعُوا الذِّكْرَ﴾ [القلم: 51].",
            "hindi": "क़ुरआन पर चलने का अर्थ यह नहीं कि उस पर चलने वाले को कभी कष्ट नहीं पहुँचेगा; नबी ﷺ को भी षड्यंत्र और ईर्ष्या का सामना हुआ, और आप पर जादू का प्रभाव होना भी प्रमाणित है; क़ुरआन सुनकर अत्यंत क्रोधित होने वालों के बारे में आया है: «और वे लोग जिन्होंने इनकार किया, निश्चय क़रीब हैं कि वे अपनी निगाहों से (घूर घूरकर) आपको अवश्य ही फिसला देंगे, जब वे क़ुरआन को सुनते हैं»।",
            "quote_bindings": [
              "Q:129"
            ]
          },
          {
            "id": "p14.s19",
            "arabic": "فالمطلوب أن يعرف المؤمن إلى من يلجأ إذا واجه الأذى، لا أن يظن أن مجرد سلوكه طريق الحق يمنع وقوعه.",
            "hindi": "ईमान वाले को जानना चाहिए कि कष्ट मिलने पर वह किसकी ओर जाए, यह नहीं समझना चाहिए कि केवल सत्य के रास्ते पर चलने से कष्ट आ ही नहीं सकता।",
            "quote_bindings": []
          },
          {
            "id": "p14.s20",
            "arabic": "ولهذا يكون حضور القلب واليقين مهمين في الاستعاذة؛ لا يقرأ المرء أسماء ربه وهو غافل عمن يدعوه، ثم يتعامل مع القراءة كأنها ألفاظ تعمل وحدها.",
            "hindi": "इसीलिए शरण माँगने में दिल की उपस्थिति और विश्वास महत्वपूर्ण हैं; मनुष्य अपने रब के नाम पढ़े, लेकिन जिसे पुकार रहा है उससे ग़ाफ़िल रहे, फिर पढ़ने को ऐसे शब्द समझे जो अपने आप काम करते हैं, ऐसा नहीं होना चाहिए।",
            "quote_bindings": []
          },
          {
            "id": "p14.s21",
            "arabic": "ويقرب هذا المعنى قولهم: «العصا بضاربها، والفاتحة بقارئها»؛ فكما لا تنفصل فاعلية الأداة عن حال من يستعملها، لا تُفصل الاستعاذة عن إخلاص المستعيذ وتعلقه بالله.",
            "hindi": "एक कहावत इस बात को समझने में मदद करती है: «लाठी का प्रभाव उसे चलाने वाले पर निर्भर है, और फ़ातिहा का प्रभाव उसे पढ़ने वाले पर।» जैसे किसी साधन का प्रभाव उसे इस्तेमाल करने वाले की दशा से अलग नहीं, वैसे ही शरण माँगने को माँगने वाले के इख़लास और अल्लाह से उसके लगाव से अलग नहीं किया जाता।",
            "quote_bindings": [
              "N:131"
            ]
          },
          {
            "id": "p14.s22",
            "arabic": "والذي يقدر الفرج ووقته هو الله؛ فلا يحدد العبد موعد الإجابة، وإن أخلص في دعائه.",
            "hindi": "राहत और उसका समय अल्लाह तय करता है; बंदा अपनी दुआ में सच्चा हो तब भी जवाब का समय स्वयं तय नहीं करता।",
            "quote_bindings": []
          },
          {
            "id": "p14.s23",
            "arabic": "وفي الاستعاذة برب الفلق ما يذكّره بتربية ربه ولطف تدبيره؛ فقد يأتي الفرج متدرجًا كما يتدرج خروج الصباح من الليل؛ فتظل تلجأ إليه ولا تجعل صحة توجهك إليه مشروطة بانكشاف ما تكرهه في اللحظة التي تختارها.",
            "hindi": "सुबह के रब की शरण लेने से उसे अपने रब का पालन और उसकी कोमल व्यवस्था याद आती है; हो सकता है राहत भी धीरे-धीरे आए, जैसे रात से सुबह धीरे-धीरे निकलती है; इसलिए उसी की ओर लौटते रहिए, और यह शर्त न रखिए कि उसकी ओर आपका रुख़ तभी सही होगा जब आपकी अप्रिय स्थिति आपके चुने हुए क्षण में ही दूर हो जाए।",
            "quote_bindings": []
          },
          {
            "id": "p14.s24",
            "arabic": "هكذا تخرج من ختام المصحف بعقيدة تعمل بها: لا نظير لربك تتوجه إليه من دونه، ولا غنى لقلبك عن رحمته وهدايته وحفظه.",
            "hindi": "यों आप क़ुरआन के अंत से एक ऐसा विश्वास लेकर उठते हैं जिसके अनुसार जीना है: आपके रब जैसा कोई नहीं जिसकी ओर उसे छोड़कर जाएँ, और आपका दिल उसकी दया, मार्गदर्शन और सुरक्षा से कभी बेनियाज़ नहीं।",
            "quote_bindings": []
          }
        ]
      }
    ]
